Rules.InvariantScript:
If(
    IsBlank(txtRut.Text),
    Notify("Por favor, ingresa un RUT antes de procesar.", NotificationType.Warning),

    If(
        drpMode.Selected.Value <> "Consultar" && Upper(Trim(txtConfirmation.Text)) <> "ELIMINAR",
        Notify("Para ejecutar una eliminación debes escribir ELIMINAR en el campo de confirmación.", NotificationType.Error),

        Set(varProcesando, true);

        Notify(
            "Procesando solicitud para el RUT " & txtRut.Text & "...",
            NotificationType.Information,
            30000
        );

        IfError(
            Set(varRutProcesado, txtRut.Text);
            Set(varModoProcesado, drpMode.Selected.Value);

            Set(
                varRespuesta,
                MotorDynamicsAPI.ExecuteSingle(
                    txtRut.Text,
                    drpMode.Selected.Value,
                    If(drpMode.Selected.Value = "Consultar", "", txtConfirmation.Text)
                )
            );

            Set(varResult, First(varRespuesta.results));

            Set(
                varNombreContacto,
                If(
                    varResult.status = "Consultado",
                    Coalesce(varResult.data.fullname, "Contacto no encontrado"),
                    ""
                )
            );

            If(
                varModoProcesado = "Consultar" && varResult.status = "Consultado",
                ClearCollect(colMatrix, varResult.data.matrix)
            );

            If(
                varModoProcesado <> "Consultar" && varResult.status = "Eliminado",
                Clear(colMatrix)
            );

            Notify(
                If(
                    varResult.status = "Eliminado",
                    "RUT " & varRutProcesado & " eliminado correctamente. Modo: " & varModoProcesado,
                    If(
                        varResult.status = "Bloqueado",
                        "Operación bloqueada para el RUT " & varRutProcesado & ". Revise confirmación o seguridad del servidor.",
                        If(
                            varResult.status = "Consultado",
                            "Consulta finalizada para el RUT " & varRutProcesado,
                            "Proceso finalizado para el RUT " & varRutProcesado & ". Estado: " & varResult.status
                        )
                    )
                ),
                If(varResult.status = "Bloqueado", NotificationType.Warning, NotificationType.Success)
            );

            Reset(txtConfirmation);
            Set(varProcesando, false),

            Set(varProcesando, false);
            Notify("Ocurrió un error al procesar la solicitud.", NotificationType.Error)
        )
    )
)

